output.output:
mark: {'type': 'bar'}
data url: {'url': 'https://cdn.jsdelivr.net/npm/vega-datasets@v3.2.1/data/population.json'}
transform:
   {'calculate': 'datum.sex === 1 ? -datum.people : datum.people', 'as': 'people_signed'}
   {'filter': 'datum.year == year'}
encoding.x: {
  "axis": {
    "format": "s",
    "labelExpr": "abs(datum.value)"
  },
  "field": "people_signed",
  "title": "Population",
  "type": "quantitative"
}
encoding.y: {
  "field": "age",
  "sort": "descending",
  "title": "Age",
  "type": "ordinal"
}
encoding.color: {
  "field": "sex",
  "legend": {
    "labelExpr": "datum.value === 1 ? 'Male' : 'Female'"
  },
  "scale": {
    "domain": [
      1,
      2
    ],
    "range": [
      "steelblue",
      "salmon"
    ]
  },
  "title": "Sex",
  "type": "nominal"
}
params: [
  {
    "name": "year",
    "bind": {
      "input": "select",
      "options": [
        1850,
        1860,
        1870,
        1880,
        1890,
        1900,
        1910,
        1920,
        1930,
        1940,
        1950,
        1960,
        1970,
        1980,
        1990,
        2000
      ],
      "name": "Year "
    },
    "value": 1980
  }
]
